import subprocess
from cryptography.fernet import Fernet
import java.util.*

def process_and_encrypt(config_file_path: str, param_dict: dict):
    # Replace placeholders in config file with actual values
    for key, value in param_dict.items():
        placeholder = f'{{{key}}}'
        command = f'sed -i ""s/{placeholder}/{value}/g"" {config_file_path}'
        try:
            subprocess.run(command.split(), check=True)
        except subprocess.CalledProcessError as e:
            raise Exception(f""Failed to replace {key} with {value}: {e}"")

    # Generate an encryption key and use it to encrypt the password
    key = Fernet.generate_key()
    cipher_suite = Fernet(key)

    # Encrypt the password using the generated key
    encrypted_password = cipher_suite.encrypt(b'your_encrypted_password_here')

    # Add encrypted password to modified config file
    command = f'echo ""{encrypted_password}"" >> {config_file_path}'
    try:
        subprocess.run(command.split(), check=True)
    except subprocess.CalledProcessError as e:
        raise Exception(""Failed to add encrypted password"")

