The main function initializes a TransactionsSet with 5 transactions and 3 metrics arrays. It then populates this structure with valid and invalid entries before calling filterTransactions with suitable parameters. Finally, it processes the returned results.",338,,"['```python
class Transaction(object):
    def __init__(self, value, age_secs):
        self.value = value
        self.age_secs = age_secs

class Metrics(object):
    def __init__(self):
        self.values = []

def filterTransactions(transactionsSet, maxAgeSecs, timeRangeSecs, thresholdValue):
    highestSum = 0
    found = False

    for transaction in transactionsSet:
        if transaction.age_secs <= maxAgeSecs and 0 <= transaction.value < thresholdValue and (transaction.age_secs % timeRangeSecs) == 0 :
            found = True
            sumProportionalToTransaction =  ((thresholdValue - transaction.value)/float(thresholdValue)) * transaction.value

            if sumProportionalToTransaction > highestSum:
                highestSum = sumProportionalToTransaction 

    return -1 if not found else highestSum

def main():
    transactionsSet = [ Transaction(i, i%10 + 1) for i in range(5) ] # Create a set of transaction with age varying from 1 to 10 seconds and values ranging from 0 to 4.

    metrics_arrays = []
    for _ in range(3):
        metric = Metrics()
        highestSum = filterTransactions(transactionsSet, 7, 2, 2) # Pass the set of transactions along with max age in seconds, time range in seconds and a threshold value.

        if highestSum != -1:
            metrics_arrays.append(highestSum)

    print(metrics_arrays) # Print the results.

if __name__ == ""__main__"":
    main()
