class JsonOperations(object):
    _registry = {}

    def __init__(self):
        pass

    @staticmethod
    def to_json(data):
        import json
        return json.dumps(data)

    @staticmethod
    def from_json(json_string, id=None):
        if id is None or id not in JsonOperations._registry:
            raise ValueError(""Invalid ID"")
        else:
            import json
            data = json.loads(json_string)
            return JsonOperations._registry[id](data)

    @classmethod
    def register_factory(cls, id, factory):
        if not callable(factory):
            raise TypeError(""Factory should be a function or class"")
        elif id in cls._registry:
            raise ValueError(""ID already exists"")
        else:
            cls._registry[id] = factory

    @classmethod
    def unregister_factory(cls, id):
        if id in cls._registry:
            del cls._registry[id]
