```python
import hashlib
import os
import threading

def compute_file_md5(file_path, chunk_size=65536):
    hash_md5 = hashlib.md5()
    with open(file_path, ""rb"") as f:
        for chunk in iter(lambda: f.read(chunk_size), b""""):
            hash_md5.update(chunk)
    return hash_md5.hexdigest()

def enhanced_file_hashing():
    global file_path, chunk_mode, chunk_size

    file_path = input(""Enter the path of the file to compute MD5 hash: "")

    if not os.path.exists(file_path) or not os.path.isfile(file_path):
        print(""Invalid file path."")
        return

    chunk_mode = input(""Do you want to compute MD5 hash in chunks? (y/n): "").lower() == 'y'

    if chunk_mode:
        try:
            chunk_size = int(input(""Enter the chunk size for hashing (default 65536): "") or 65536)
        except ValueError:
            print(""Invalid input. Using default chunk size."")
            chunk_size = 65536

    try:
        md5_hash = compute_file_md5(file_path, chunk_size) if chunk_mode else compute_file_md5(file_path)

        print(f""MD5 Hash of {file_path}: {md5_hash}"")

    except Exception as e:
        print(f""An error occurred: {str(e)}"")

def multi_threaded_hashing():
    def hash_chunk(start, end):
        global md_1024
        md_1024 = hashlib.md5()
        with open(file_path, ""rb"") as f:
            f.seek(start)
            for i in range(start, end):
                md_1024.update(f.read(chunk_size))

    file_length = os.path.getsize(file_path)

    num_threads = min(8, os.cpu_count())

    thread_list = []

    total_chunks = (file_length + chunk_size - 1) // chunk_size

    step_per_thread = total_chunks // num_threads

    for i in range(num_threads):
        start_index = i * step_per_thread
        end_index = start_index + step_per_thread

        if i == num_threads - 1:
            end_index += total_chunks % num_threads

        thread_list.append(threading.Thread(target=hash_chunk, args=(start_index, end_index)))

    for thread in thread_list:
        thread.start()

    for thread in thread_list:
        thread.join()

if __name__ == ""__main__"":
    enhanced_file_hashing()
    multi_threaded_hashing()
```
