```python
import concurrent.futures
import hashlib
import os

def chunk_reader(file, size=65536):
    while True:
        data = file.read(size)
        if not data: break
        yield data

def compute_hash(path, start, end, hasher):
    with open(path, 'rb') as f:
        f.seek(start)
        hasher.update(f.read(end-start))
    return hasher.hexdigest()

def enhanced_file_hashing(file_path):
    if not os.path.exists(file_path) or not os.path.isfile(file_path):
        print(""Invalid file path."")
        return

    chunk_mode = input(""Do you want to compute MD5 hash in chunks?  (y/n): "").lower() == 'y'

    if chunk_mode:
        try:
            chunk_size = int(input(""Enter the chunk size for hashing (default 65536): "") or 65536)

            total_chunks = (os.path.getsize(file_path) + (chunk_size - 1)) // chunk_size

            num_threads = min(8, os.cpu_count())

            hasher_list = [hashlib.md5() for _ in range(num_threads)]

            with concurrent.futures.ThreadPoolExecutor(max_workers=num_threads) as executor:
                futures = []

                for i, hasher in enumerate(hasher_list):
                    start = (os.path.getsize(file_path) // num_threads) * i

                    if i == num_threads - 1:
                        end = os.path.getsize(file_path)
                    else:
                        end = (os.path.getsize(file_path) // num_threads) * (i + 1)

                    futures.append(executor.submit(compute_hash, file_path, start, end, hasher))

                for future in concurrent.futures.as_completed(futures):
                    print(future.result())

        except ValueError:
            print(""Invalid input. Using default chunk size."")
```
Please note that this is a basic implementation and there might be more optimal methods for multi-threading file hashing depending on the specific use case or constraints of your application. Always consult with your IT department before implementing multithreading in any serious application.
