```python
from datetime import datetime

class DataEntry:
    def __init__(self, value, timestamp, id):
        self.value = value
        self.timestamp = timestamp
        self.id = id

class DataEntriesSet:
    def __init__(self):
        self.entries = []
        self.metrics = [0.0] * 3

    def add_entry(self, entry):
        self.entries.append(entry)

    def remove_entry(self, entry_id):
        for entry in self.entries:
            if entry.id == entry_id:
                self.entries.remove(entry)
                break

def process_entries(entries_set, max_age_seconds, time_range_start=0, time_range_end=3, threshold_value=10):
    if not entries_set.entries or max_age_seconds < 0 or time_range_end < time_range_start:
        return -1

    valid_entries = []
    for entry in entries_set.entries:
        if (entry.timestamp >= time_range_start and
            entry.timestamp <= time_range_end and
            abs(entry.value - threshold_value) < threshold_value and
            (entry.timestamp + max_age_seconds) > datetime.now().timestamp()):
            valid_entries.append(entry)

    if not valid_entries:
        return -1

    metric_sum = 0.0
    metric_count = 0
    for valid_entry in valid_entries:
        relative_value = abs(valid_entry.value - threshold_value)
        proportional_average = (relative_value / threshold_value) * ((datetime.now().timestamp() - valid_entry.timestamp) / max_age_seconds)
        metric_sum += proportional_average
        metric_count += 1

    highest_average_metric_index = max(range(len(entries_set.metrics)), key=lambda index: entries_set.metrics[index])

    if metric_count > 0:
        updated_metric_average = metric_sum / metric_count

        if updated_metric_average > entries_set.metrics[highest_average_metric_index]:
            entries_set.metrics[highest_average_metric_index] = updated_metric_average

    return max(entries_set.metrics)

