import ctypes
from ctypes import Structure, POINTER, pointer, byref, cast, c_void_p, c_long, c_char

class Record(Structure):
    _fields_ = [('data', POINTER(c_char)), ('length', c_long)]

def allocate_memory(size: int) -> POINTER:
    return cast(malloc(size), POINTER(c_void_p))

def deallocate_memory(ptr: POINTER):
    free(cast(ptr, c_void_p).value)

class BinaryStringTransformer:
    def __init__(self):
        self.record = Record()
        self.c_functions = CDLL(""./libctypes_test.so"")  # replace this with your actual library path

    def removeBinaryDigits(self, string):
        binary_string = ''.join([bit for bit in string if bit in ('0', '1')])
        return self._binaryToDecimalList(binary_string)

    def _binaryToDecimalList(self, binary_string):
        decimal_values = [int(binary_string[i:i+8], 2) for i in range(0, len(binary_string), 8)]
        return self._allocateMemoryForLongInts(decimal_values)

    def _allocateMemoryForLongInts(self, decimal_values):
        array = allocate_memory(c_long * len(decimal_values))
        for i in range(len(decimal_values)):
            self.record.data[i] = c_char.from_address(id(decimal_values[i]))
        self.record.length = len(decimal_values)
        return array

    def binaryToDecimal(self, string):
        decimal = 0
        for bit in string:
            decimal = decimal * 2 + int(bit)
        return decimal

    def freeMemory(self, ptr):
        deallocate_memory(ptr)
```
Please note that the above code assumes you have `libctypes_test.so` which provides malloc and free functions. You will need to replace it with your actual library path or remove if not necessary. Also, `c_functions = CDLL(""./libctypes_test.so"")` is used to load C standard library functions for memory management (malloc and free). Again, you'll need to replace this with your own library or methods depending on your requirements.
