Furthermore, implement logging to record each validation attempt along with whether it was successful or not.",680,,"['Here is the Python code for the problem as described. 

```python
import string
import random
import logging
from typing import Optional

class StringValidator:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)

    @staticmethod
    def validate_length(input_string: str) -> bool:
        return 5 <= len(input_string) <= 20

    @staticmethod
    def validate_starts_with_letter(input_string: str) -> bool:
        return input_string[0].isalpha()

    @staticmethod
    def validate_contains_digit(input_string: str) -> bool:
        return any(char.isdigit() for char in input_string)

    @staticmethod
    def validate_no_special_chars_or_spaces(input_string: str) -> bool:
        return all(char not in string.punctuation and char != ' ' for char in input_string)

    def validate(self, input_string: Optional[str]) -> bool:
        if input_string is None:
            self.logger.info(""Validation attempt failed: input was null"")
            return False

        checks = [
            self.validate_length(input_string),
            self.validate_starts_with_letter(input_string),
            self.validate_contains_digit(input_string),
            self.validate_no_special_chars_or_spaces(input_string)
        ]

        if all(checks):
            self.logger.info(""Validation attempt successful: '%s' passed all checks"", input_string)
            return True

        self.logger.info(""Validation attempt failed: '%s' did not pass all checks"", input_string)
        return False

    @staticmethod
    def generate_valid_string():
        valid_chars = string.ascii_letters + string.digits  # Characters allowed in the string
        length = random.randint(5, 20)  # Random length between 5 and 20
        generated_str = ''.join(random.choice(valid_chars) for _ in range(length))

        while not (generated_str[0].isalpha() and any(char.isdigit() for char in generated_str)):
            # Re-generate string until it starts with a letter and contains at least one digit
            generated_str = ''.join(random.choice(valid_chars) for _ in range(length))

        return generated_str

    def test_validation(self):
        # Generate 10 random valid strings and validate them
        for _ in range(10):
            random_string = self.generate_valid_string()
            assert self.validate(random_string), f""Failed to validate string: {random_string}""

        print(""All tests passed"")

if __name__ == ""__main__"":
    validator = StringValidator()
    validator.test_validation()
```
This code includes a StringValidator class with methods for each of the validation criteria, as well as error handling and logging. The generate_valid_string method generates random strings that meet the defined rules, which are used to test the validate method in the test_validation method.
