1,"Create a function named `processOrderRequest` that takes an order request as input. The function should check if the request contains 'action' and 'order_id'. If it does, and the action is 'cancel', the function should remove the order with the specified order_id from a predefined list of orders. If the action is 'update', the function should update the order with new data provided in the request, such as 'status' and 'items'. If no specific action is provided or if there's no order_id, the function should add a new order to the list with data from the request, including 'customer_name', 'items', and calculate a total price based on item prices.",601,,"['```python
orders = [{'order_id': 1, 'status': 'paid', 'items': ['item1', 'item2'], 'total_price': 50}, {'order_id': 2, 'status': 'unpaid', 'items': ['item3'], 'total_price': 40}]

def processOrderRequest(request):
    if not isinstance(request, dict) or ('action' not in request and 'order_id' not in request):
        return ""Invalid order request""

    action = request.get('action')
    order_id = request.get('order_id')

    if action == 'cancel':
        for index, order in enumerate(orders):
            if order['order_id'] == order_id:
                orders.pop(index)
                return ""Order cancelled""

    elif action == 'update':
        for order in orders:
            if order['order_id'] == order_id:
                order.update((k, v) for k, v in request.items() if k not in ['action', 'order_id'])
                return ""Order updated""

    # Create a new order if no action or order_id is specified
    else:
        item_prices = {'item1': 20, 'item2': 30}   # This should be replaced by real prices. It's just for the sake of example here

        total_price = 0
        items = request['items']
        for item in items:
            if item not in item_prices:
                return f""Unknown item '{item}'""

            total_price += item_prices[item]

        new_order = {'order_id': len(orders) + 1, 'status': 'unpaid', 'items': items, 'total_price': total_price}
        new_order.update((k, v) for k, v in request.items() if k not in ['action', 'order_id'])

        orders.append(new_order)
        return ""Order created""
``` 

