class FontCacheManager:
    def __init__(self, default_font_dirs=None, default_cache_dir=""cache"", supported_extensions=["".ttf"", "".otf""], delete_original=True):
        self.default_font_dirs = default_font_dirs if default_font_dirs else [""fonts""]
        self.default_cache_dir = default_cache_dir
        self.supported_extensions = supported_extensions
        self.cache_directories = [join(default_cache_dir, ""v"" + str(i)) for i in range(1)]
        self._font_cache = {}

    def load_font(self, font_file_path):
        hash_value = get_file_hash(font_file_path)
        if hash_value in self._font_cache:
            return self._font_cache[hash_value]

        try:
            version = 1  

            while True:
                full_filename_v = join(self.cache_directories[version], os.path.basename(font_file_path))

                try:
                    shutil.copy2(font_file_path, full_filename_v)
                    content_hash = get_file_hash(full_filename_v)

                    if content_hash == hash_value:   
                        self._font_cache[hash_value] = full_filename_v  
                        return full_filename_v

                    else:    
                        version += 1

                except FileExistsError:
                    print(f""Font {os.path.basename(font_file_path)} at {full_filename_v} already exists."")

        except FileNotFoundError:
            print(f""Font file '{font_file_path}' not found."")
            return None
