def prime_sum_calculator(start: int, end: int):
    if not isinstance(start, int) or not isinstance(end, int):
        return ""Error: Invalid input. Please provide integer values.""

    if start < 0 or end < 0:
        return ""Error: Range cannot be negative.""

    primes = []
    if start > end:
        start, end = end, start

    for num in range(start, end + 1):
        if num > 1:
            for i in range(2, num):
                if num % i == 0:
                    break
            else:
                primes.append(num)

    return sum(primes)

def interface():
    print(""Select operation:\n 1. Update SQLite record \n 2. Calculate prime number sum"")
