    elif choice == '2':
        start = int(input('Enter start of range: '))
        end = int(input('Enter end of range: '))

        print(prime_sum_calculator(start, end))
    else:
        print(""Invalid option. Try again."")
        interface()

if __name__ == ""__main__"":
