```python
class EfficientMatrixCalculator:
    def __init__(self, matrix1, matrix2):
        self.matrix1 = matrix1
        self.matrix2 = matrix2

    def add(self):
        if len(self.matrix1) != len(self.matrix2) or len(self.matrix1[0]) != len(self.matrix2[0]):
            raise ValueError(""Matrix dimensions are not compatible for addition."")

        return [[self.matrix1[i][j] + self.matrix2[i][j]  for j in range(len(self.matrix1[0]))] for i in range(len(self.matrix1))]

    def subtract(self):
        if len(self.matrix1) != len(self.matrix2) or len(self.matrix1[0]) != len(self.matrix2[0]):
            raise ValueError(""Matrix dimensions are not compatible for subtraction."")

        return [[self.matrix1[i][j] - self.matrix2[i][j]  for j in range(len(self.matrix1[0]))] for i in range(len(self.matrix1))]

    def multiply(self):
        if len(self.matrix1[0]) != len(self.matrix2):
            raise ValueError(""Matrix dimensions are not compatible for multiplication."")

        return [[sum(a*b for a, b in zip(row_a, col_b)) for col_b in zip(*self.matrix2)] for row_a in self.matrix1]

def read_file(filepath):
    matrix = []
    with open(filepath) as f:
        for line in f:
            matrix.append([int(x) for x in line.split()])
    return matrix

def write_file(filepath, matrix):
    with open(filepath, 'w') as f:
        for row in matrix:
            f.write(' '.join(map(str,row)) + '\n')

