                employee.salary = salary
                self._salaries_by_dept[employee.department].append(employee.salary)
            if department is not None:
                self._salaries_by_dept[employee.department].remove(employee.salary)
                employee.department = department
                self._salaries_by_dept[employee.department].append(employee.salary)

