class FileHashingThread(threading.Thread):
    def __init__(self, filename, start=0, end=None):
        super().__init__()
        self.filename = filename
        self.start = start
        self.end = end if end else os.path.getsize(filename)

    def run(self):
        with open(self.filename, 'rb') as f:
            f.seek(self.start)
            data = f.read(self.end-self.start+1)
