import hashlib
import threading
import time
from dataclasses import dataclass
from typing import List, Tuple

@dataclass
class NFAPI_CRC_INDICATION_PDU_T:
    """"""Data structure for NFAPI_CRC_INDICATION_PDU_T used in network communications.""""""
    payload: bytes

def calculate_prime_sum(data: List[int]) -> int:
    """"""Calculate the sum of all prime numbers within a given range.""""""
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    return sum(x for x in data if is_prime(x))

def calculate_md5_hash(file_path: str) -> str:
    """"""Compute the MD5 hash of a specified file using threading for improved performance.""""""
    def hash_thread(file_path: str):
        with open(file_path, 'rb') as file:
            md5 = hashlib.md5()
            while True:
                chunk = file.read(4096)
                if not chunk:
                    break
                md5.update(chunk)
            return md5.hexdigest()

    threads = []
    thread_output = []

    start_time = time.time()

    with open(file_path, 'rb') as file:
        total_chunks = (file.seek(0, 2) // 4096 + (file.tell() % 4096 != 0))

        for i in range(total_chunks):
            threads.append(threading.Thread(target=lambda f, s=i: thread_output.append(hash_thread(f)[s*4096:(s+1)*4096])))

        [t.start() for t in threads]
        [t.join() for t in threads]

        full_md5_hash = ''.join(thread_output)

    end_time = time.time()

    print(f""MD5 hash computation took {end_time - start_time:.2f} seconds."")

return full_md5_hash

