```python
import numpy as np

class EfficientMatrixCalculator:
    def __init__(self):
        self._matrix1 = None
        self._matrix2 = None

    @staticmethod
    def read_matrix(filepath):
        try:
            with open(filepath, ""r"") as f:
                lines = f.readlines()
                matrix = [list(map(float, line.strip().split())) for line in lines]
            return np.array(matrix)
        except IOError:
            print(""There was an error reading the file."")
            raise

    @staticmethod
    def write_matrix(filepath, matrix):
        try:
            with open(filepath, ""w"") as f:
                for row in matrix.tolist():
                    row = ' '.join(map(str, row))  # convert numbers to strings
                    f.write(""%s\n"" % row)
        except IOError:
            print(""There was an error writing the file."")

    def validate_dimensions(self):
        if self._matrix1 is None or self._matrix2 is None:
            raise ValueError(""Matrices are not set"")
        elif self._matrix1.shape != self._matrix2.shape:
            raise ValueError(""Matrix dimensions do not match"")

    def add_matrices(self):
        self.validate_dimensions()
        return self._matrix1 + self._matrix2

    def subtract_matrices(self):
        self.validate_dimensions()
        return self._matrix1 - self._matrix2

    def multiply_matrices(self):
        self.validate_dimensions()
        return np.dot(self._matrix1, self._matrix2)

