import json
import xml.etree.ElementTree as ET
import os
import base64

class ResourceLoader:
    def __init__(self, settings):
        self.settings = settings
        self.cache = {}
        self.max_items_per_bundle = settings.get('max_items_per_bundle', 100)
        self.serialization_format = settings.get('serialization_format', 'json')

    def load_multiple_files(self, bundle_selections):
        loaded_data = {}
        for bundle_selection in bundle_selections:
            bundle_file, _bundle_name = bundle_selection
            try:
                if self.serialization_format == 'json':
                    with open(bundle_file) as f:
                        data = json.load(f)
                elif self.serialization_format == 'xml':
                    tree = ET.parse(bundle_file)
                    data = tree.getroot()
                else:
                    raise ValueError(""Unsupported serialization format"")

                if len(data) > self.max_items_per_bundle:
                    raise ValueError(f""Exceeded maximum items per bundle in {bundle_file}"")

                loaded_data[_bundle_name] = data

            except FileNotFoundError as e:
                print(f""File not found: {bundle_file}. Error: {e}"")
            except (json.JSONDecodeError, ET.ParseError) as e:
                print(f""Invalid file: {bundle_file}. Error: {e}"")
            except ValueError as e:
                print(f""{e} at file: {bundle_file}"")

        return loaded_data

    def cache_load(self, _bundle_name):
        if _bundle_name in self.cache and not self.settings.get('clear_cache', False):
            return self.cache[_bundle_name]

    def cache_store(self, _bundle_name, data):
        if not self.settings.get('clear_cache', False):
            self.cache[_bundle_name] = data

    def encrypt_decrypt(self, content, encryption_key):
        encrypted_content = base64.b64encode(content.encode()).decode()
        decrypted_content = base64.b64decode(encrypted_content).decode()

        return decrypted_content
