```",327,,"['Here's the Python code for your problem. Note that there is no padding scheme defined in this version, so it only supports HMACSHA256Signer without any padding or MAC generation schemes like ANSI X9.17 and PKCS#1 v1.5. 

```python
import os
from cryptography.hazmat.primitives import hashes, hmac
from cryptography.exceptions import InvalidSignature

class HMACSHA256Signer:
    def __init__(self, key: bytes = None, key_size: int = 256, random_mac: bool = False):
        self.key_size = key_size

        if key is None:
            if random_mac:
                self.key = os.urandom(key_size // 8)
            else:
                raise ValueError(""Key must be provided for HMACSHA256Signer"")
        else:
            if len(key) * 8 != key_size:
                raise ValueError(f""Key size must be {key_size} bits"")
            self.key = key

    def _generate_signature(self, message: bytes) -> bytes:
        hash_algorithm = hashes.SHA256()
        hmac_obj = hmac.HMAC(self.key, hash_algorithm)
        hmac_obj.update(message)
        return hmac_obj.finalize()

    def generate_signature(self, message: bytes) -> bytes:
        return self._generate_signature(message)

    def verify_signature(self, message: bytes, signature: bytes) -> bool:
        hash_algorithm = hashes.SHA256()
        hmac_obj = hmac.HMAC(self.key, hash_algorithm)
        hmac_obj.update(message)

        try:
            hmac_obj.verify(signature)
        except InvalidSignature:
            return False

        return True

class SignatureGenerationError(Exception):
    pass
``` 

You might need to install the `cryptography` library if you haven't already using pip:
```sh
pip install cryptography
```
