```python
import math
import hashlib
from random import randint
from multiprocessing import Pool

def is_prime(n):
    if n <= 1:
        return False
    elif n == 2 or n == 3:
        return True
    elif n % 2 == 0:
        return False
    else:
        for i in range(3, int(math.sqrt(n)) + 1, 2):
            if n % i == 0:
                return False
        return True

def prime_sum_calculator(start, end):
    if not isinstance(start, int) or not isinstance(end, int):
        print(""Error: Non-integer input."")
        return None
    elif start < 0 or end < 0:
        print(""Error: Negative input."")
        return None

    return sum([i for i in range(start, end+1) if is_prime(i)])

def create_and_process_NFAPI_CRC_INDICATION_PDU_T_structures():
    RX_UE_INFORMATION_TAG = randint(0, 2**64 - 1)
    RNTI = randint(0, 2**32 - 1)
    CRC_INDICATION_REL8_TAG = randint(0, 2**8 - 1)

    return {
        ""RX_UE_INFORMATION_TAG"": RX_UE_INFORMATION_TAG,
        ""RNTI"": RNTI,
        ""CRC_INDICATION_REL8_TAG"": CRC_INDICATION_REL8_TAG
    }

def chunked(file, size=1024):
    while True:
        data = file.read(size)
        if not data:
            break
        yield data

def sequential_hash(path):
    h = hashlib.md5()

    with open(path, 'rb') as f:
        for chunk in chunked(f):
            h.update(chunk)

    return h.hexdigest()

def parallel_hash(path, processes=8):
    pool = Pool(processes)

    with open(path, 'rb') as f:
        results = pool.map(hashlib.md5, chunked(f))

    h = hashlib.md5()

    for result in results:
        h.update(result.digest())

    return h.hexdigest()

def enhanced_file_hashing(path, use_parallel=False):
    if use_parallel:
        return parallel_hash(path)

    return sequential_hash(path)
```
