import socket
import pandas as pd
from io import StringIO

def resolve_domain_dns(email):
    try:
        domain = email.split('@')[1]
        return socket.gethostbyname(domain)
    except Exception as e:
        print(f""An error occurred during DNS resolution for {email}: {str(e)}"")
        return None

def process_csv(input_file, output_file):
    try:
        data = pd.read_csv(input_file)
        domains = []
        for email in data['Email']:
            domain = resolve_domain_dns(email)
            if domain is not None:
                domains.append({'Email': email, 'Domain': domain})
        result = pd.DataFrame(domains)
        result.to_csv(output_file, index=False)
    except Exception as e:
        print(f""An error occurred during CSV processing: {str(e)}"")
```
