```python
import socket
import os

def resolve_dns(domain):
    try:
        return socket.gethostbyname(domain)
    except socket.gaierror as e:
        print(""Error during name resolution: "", str(e))
        return None

def main():
    if os.getuid() != 0:  # Check for root privileges
        domain = input(""Enter a domain to resolve: "")
        ip_address = resolve_dns(domain)

        if ip_address is not None:
            print(""Resolved IP address: "", ip_address)
    else:
        print(""This script must not be run with root privileges."")

if __name__ == ""__main__"":
    main()
```

