def enhanced_file_hashing(filename, mode='sequential', chunk_size=4096, parallel_processes=2):
    if not os.path.isfile(filename):
        raise ValueError(""The provided file does not exist"")

    with open(filename, 'rb') as f:
        if mode == 'sequential':
            md5 = hashlib.md5()
            chunk = f.read(chunk_size)
            while chunk:
                md5.update(chunk)
                chunk = f.read(chunk_size)
            return md5.hexdigest()

        elif mode == 'parallel':
            md5 = hashlib.md5()
            processes = []
            queue = Queue()

            while True:
                chunk = f.read(chunk_size)
                if not chunk:
                    break

                p = Process(target=hash_chunk, args=(chunk, queue))
                processes.append(p)
                p.start()

                if len(processes) >= parallel_processes or f.tell() == os.path.getsize(filename):
                    while not queue.empty():
                        md5.update(queue.get())

                    for p in processes:
                        if p.is_alive():
                            p.join()
                    processes = []

            return md5.hexdigest()
