```python
import math
from typing import List
from functools import lru_cache, wraps

# caching decorator
def cache(func):
    cached = {}
    @wraps(func)
    def wrapper(*args):
        if args not in cached:
            cached[args] = func(*args)
        return cached[args]
    return wrapper

@lru_cache(maxsize=None)  # memoization for prime checking
def is_prime(n: int) -> bool:
    if n < 2:
        return False
    for i in range(2, math.isqrt(n) + 1):  # only need to check up to sqrt of n
        if n % i == 0:
            return False
    return True

@cache   # caching prime checks and results
def prime_and_square(numbers: List[int]) -> list:
    """"""
    Returns a new list containing only elements that are both prime numbers and perfect squares.

    Args:
        numbers (List[int]): The list of integers to process.

    Raises: 
        ValueError: If the input is not a list, or if any element in the list is not an integer.

    Returns:
        List: A new list containing elements that are both prime numbers and perfect squares from the input list.
    """"""

    # Validating inputs
    if type(numbers) != list:
        raise ValueError(""Input should be a list"")
    for num in numbers:
        if not isinstance(num, int):
            raise ValueError(""All elements in the input list should be integers."")

    result = []
    for num in numbers:
        # Skip non-positive numbers and perfect squares that are not prime 
        if num <= 0 or (math.isqrt(num) ** 2 != num and is_prime(num)):  
            continue

        # Check if the number is both a prime and a square
        if math.isqrt(num) ** 2 == num and is_prime(num):   
            result.append(num)

    return result
```
In this solution, `functools.lru_cache` is used for memoization to store previously calculated prime checks, thus reducing redundant calculations. Similarly, the `@cache` decorator function is created for storing the results of previous calculations and checking for duplicates in the input list. If any non-integer or non-list elements are present, a ValueError will be raised.
