```python
class Character:
    def __init__(self, name, health):
        self.name = name
        self.health = health

class Attack:
    def __init__(self, name, damage, cooldown):
        self.name = name
        self.damage = damage
        self.cooldown = cooldown
        self.last_used = 0

    def use(self, character, time):
        if time - self.last_used < self.cooldown:
            print(""Attack is still on cooldown."")
            return

        self.last_used = time
        character.health -= self.damage
        print(f""{self.name} attack does {self.damage} damage to {character.name}"")

class Game:
    def __init__(self):
        self.time = 0
        self.player = Character(""Player"", 100)

        # Initialize attacks with different cooldowns
        self.attacks = [Attack(""Slash"", 20, 9), Attack(""Stab"", 30, 12)]

    def choose_attack(self):
        for i, attack in enumerate(self.attacks):
            print(f""{i}: {attack.name} (cooldown: {attack.cooldown})"")

        choice = int(input(""Choose an attack: ""))
        if 0 <= choice < len(self.attacks):
            self.attacks[choice].use(self.player, self.time)

    def start(self):
        while self.player.health > 0:
            print(f""Time: {self.time}, Player health: {self.player.health}"")
            self.choose_attack()
            self.time += 1

        print(""Game Over."")

game = Game()
game.start()
```
