import hashlib
import os
from typing import Generator

class FileHasher:
    def __init__(self, file_path: str):
        self.file_path = file_path
        try:
            self.hash_object = hashlib.md5()
        except Exception as e:
            print(f'Error occurred while initializing the hash object: {e}')

    def add_chunk(self, chunk) -> None:
        try:
            self.hash_object.update(chunk)
        except Exception as e:
            print(f'Error occurred while incorporating data chunks: {e}')

    def digest(self) -> str:
        try:
            return self.hash_object.hexdigest()
        except Exception as e:
            print(f'Error occurred while retrieving the hexadecimal digest: {e}')

    def yield_chunk(self, chunk_size=8192) -> Generator[bytes, None, None]:
        try:
            with open(self.file_path, 'rb') as f:
                while True:
                    data = f.read(chunk_size)
                    if not data:
                        break
                    yield data

        except Exception as e:
            print(f'Error occurred while reading the file: {e}')
