    def __init__(self, max_size_per_version=50 * (2**30), cache_expiry_days=30, **kwargs):
        super().__init__(**kwargs)
        self.max_size_per_version = max_size_per_version
        self.cache_expiry_days = cache_expiry_days

    def manage_caches(self):
        for dirpath, dirs, files in os.walk(""input_folder""):
            for file in files:
                file_path = path.join(dirpath, file)
                _, ext = path.splitext(file_path)

                if ext.lower() not in self.supported_extensions:
                    continue

                creation_date = datetime.fromtimestamp(os.stat(file_path).st_ctime)
                if (datetime.now() - creation_date) > timedelta(days=self.cache_expiry_days):
                    remove(file_path)
```
