from Crypto.Cipher import DES, AES
from Crypto.Util.Padding import pad, unpad

class ConfigDBLinkage:
    def __init__(self):
        self.auth_details = {
            ""username"": os.environ.get(""USERNAME""),  # Fetch from environmental variables
            ""password"": os.environ.get(""PASSWORD"")   # Fetch from environmental variables
        }

    def create_config(self, filepath):
        with open(filepath, 'w') as config_file:
            for key, value in self.auth_details.items():
                config_file.write(""{}={}\n"".format(key, value))

class CryptographicSystem:
    def __init__(self):
        self.cipher = DES.new(os.urandom(8), DES.MODE_ECB)   # Default mode is ECB

    def set_mode(self, mode):
        modes = {
            ""ecb"": DES.MODE_ECB,
            ""ede"": DES.MODE_CBC,
            ""ede3"": AES.MODE_OFB,  # AES uses OFB mode for EDE3
            ""cfb"": DES.MODE_CFB   
        }

        if mode in modes:
            self.cipher = DES.new(os.urandom(8), modes[mode])   # Change the cipher based on selected mode

    def decrypt(self, base64_encoded):
        return self.cipher.decrypt(base64.b64decode(base64_encoded)).decode()

    def encrypt(self, plaintext):
        return base64.b64encode(self.cipher.encrypt(pad(plaintext.encode(), DES.block_size))).decode()
